def saveSettings(self, groupName=None):
        """ Writes the registry items into the persistent settings store.
        """
        if groupName is None:
            groupName = self.groupName
        if groupName is None:
            raise ValueError("No group name specified")
        if self.settings is None:
            raise ValueError("No settings to save")
        if not self.settings.has_key(groupName):
            raise ValueError("No settings for group %s" % groupName)
        settings = self.settings[groupName]
        for key, value in settings.items():
            self.setSetting(key, value, groupName)

